import { useId, type ReactNode } from "react"

import { GridSection } from "@/registry/ui/grid-layout/grid-layout"

import type { ProfileHeroLabels } from "./config"
import { RoleRotator } from "./role-rotator"

/**
 * 个人封面：斜纹横幅 + 头像 + 名字 + 简介 + 职业标签轮播。放在 GridContainer 内使用。
 * 名字、简介、职业标签都是页面数据；按钮文案通过 labels 覆盖。
 */
function ProfileHero({
  name,
  bio,
  roles = [],
  initials,
  avatar,
  tagline = "DESIGN · CODE · REPEAT",
  labels,
  className,
}: {
  /** 显示的名字，会作为页面的 h1 */
  name: string
  /** 一两句话的自我介绍 */
  bio: string
  /** 职业标签，会依次轮播 */
  roles?: readonly string[]
  /** 未传 avatar 时，头像位置显示的缩写（1–2 个字符） */
  initials?: string
  /** 自定义头像节点，传入后替换缩写方块 */
  avatar?: ReactNode
  /** 横幅中间的装饰文字，设为空字符串可隐藏 */
  tagline?: string
  /** 覆盖默认文案，见 config.ts 的 DEFAULT_LABELS */
  labels?: Partial<ProfileHeroLabels>
  className?: string
}) {
  const titleId = useId()
  return (
    <GridSection
      data-slot="profile-hero"
      aria-labelledby={titleId}
      className={className}
    >
      <div
        data-slot="profile-hero-banner"
        aria-hidden="true"
        className="relative flex h-32 items-center justify-center overflow-hidden bg-muted/20 sm:h-44"
      >
        <div className="absolute inset-0 bg-hatch opacity-40" />
        {tagline ? (
          <div className="relative flex items-center gap-5 font-mono text-muted-foreground/70">
            <span className="text-4xl font-extralight sm:text-5xl">{"{ "}</span>
            <span className="text-xs tracking-[0.35em]">{tagline}</span>
            <span className="text-4xl font-extralight sm:text-5xl">{" }"}</span>
          </div>
        ) : null}
      </div>
      <div className="relative flex flex-col gap-5 px-4 pb-7 sm:px-6">
        {avatar ?? (
          <div
            aria-hidden="true"
            className="relative -mt-10 flex size-20 items-center justify-center rounded-2xl border border-edge bg-background font-mono text-3xl font-medium tracking-tighter ring-4 ring-background"
          >
            {initials ?? name.slice(0, 1)}
          </div>
        )}
        <div className="flex flex-col gap-2">
          <h1
            id={titleId}
            className="text-3xl font-semibold tracking-tight sm:text-4xl"
            translate="no"
          >
            {name}
            <span className="text-primary">.</span>
          </h1>
          <p className="text-sm leading-7 text-pretty text-muted-foreground sm:text-base">
            {bio}
          </p>
          <RoleRotator roles={roles} labels={labels} />
        </div>
      </div>
    </GridSection>
  )
}

export { ProfileHero }

/**
 * 个人封面的界面文案。
 * 姓名、简介、职业标签属于页面数据，通过 ProfileHero 的 props 传入，不放在这里。
 */
const DEFAULT_LABELS = {
  pauseRoles: "暂停职业标签",
  playRoles: "播放职业标签",
} as const

type ProfileHeroLabels = { [Key in keyof typeof DEFAULT_LABELS]: string }

/** 合并用户传入的文案与默认文案。 */
function resolveLabels(labels?: Partial<ProfileHeroLabels>): ProfileHeroLabels {
  return { ...DEFAULT_LABELS, ...labels }
}

export { DEFAULT_LABELS, resolveLabels }
export type { ProfileHeroLabels }

"use client"

import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { useEffect, useState } from "react"

import { resolveLabels, type ProfileHeroLabels } from "./config"

/** 职业标签轮播：每 3.2 秒切换一次，可暂停；系统开启「减少动态效果」时不自动轮播。 */
function RoleRotator({
  roles,
  labels,
}: {
  roles: readonly string[]
  labels?: Partial<ProfileHeroLabels>
}) {
  const text = resolveLabels(labels)
  const reducedMotion = useReducedMotion()
  const [index, setIndex] = useState(0)
  const [paused, setPaused] = useState(false)
  useEffect(() => {
    if (reducedMotion || paused || roles.length < 2) return
    const timer = window.setInterval(
      () => setIndex((value) => (value + 1) % roles.length),
      3200,
    )
    return () => window.clearInterval(timer)
  }, [paused, reducedMotion, roles.length])
  if (!roles.length) return null
  return (
    <div
      data-slot="profile-hero-role-rotator"
      data-paused={paused ? "" : undefined}
      className="flex min-h-7 items-center gap-3 font-mono text-sm text-muted-foreground"
    >
      <span aria-hidden="true" className="text-primary">
        ↳
      </span>
      {/* 读屏一次性读出全部标签，视觉上的轮播对读屏隐藏 */}
      <span className="sr-only">{roles.join("、")}</span>
      {/* 所有标签叠在同一个 grid 单元里：隐形副本把宽度撑到最长那项，切换时暂停按钮不会左右跳 */}
      <span aria-hidden="true" className="grid min-w-0">
        {roles.map((role) => (
          <span key={role} className="invisible col-start-1 row-start-1">
            {role}
          </span>
        ))}
        <AnimatePresence mode="wait" initial={false}>
          <motion.span
            key={index}
            className="col-start-1 row-start-1"
            initial={{ opacity: 0, y: reducedMotion ? 0 : 5 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: reducedMotion ? 0 : -5 }}
            transition={{ duration: 0.18 }}
          >
            {roles[index]}
          </motion.span>
        </AnimatePresence>
      </span>
      {roles.length > 1 ? (
        <button
          type="button"
          onClick={() => setPaused((value) => !value)}
          aria-label={paused ? text.playRoles : text.pauseRoles}
          aria-pressed={paused}
          className="inline-flex size-7 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring motion-reduce:hidden"
        >
          {/* 两个图标同一画布、同一尺寸、同为实心，切换时按钮外观不跳动 */}
          <svg
            viewBox="0 0 24 24"
            fill="currentColor"
            aria-hidden="true"
            className="size-3.5"
          >
            {paused ? (
              <path d="M7 5.6v12.8a1 1 0 0 0 1.5.86l10.8-6.4a1 1 0 0 0 0-1.72L8.5 4.74A1 1 0 0 0 7 5.6Z" />
            ) : (
              <>
                <rect x="6" y="5" width="4" height="14" rx="1" />
                <rect x="14" y="5" width="4" height="14" rx="1" />
              </>
            )}
          </svg>
        </button>
      ) : null}
    </div>
  )
}

export { RoleRotator }
